import {scenarioParts,insertScenarioStep} from './scenario.js';
import {countdown} from './preview-timer.js';
import {uid,kinds,step,question,theme,initial,questions,issues,questionTypes,questionType,answerLabel} from './model.js';
import {exportSIQ,importSIQ} from './siq.js';
import * as storage from './storage.js';
import {installStepDrag,reorderSteps} from './step-drag.js';
import {welcomeHTML} from './welcome.js';
import {defaultSetup,setupHTML,setupRoundsHTML,setupPreviewHTML,buildPack} from './setup.js';
const $=s=>document.querySelector(s),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,label,cls='',extra='')=>`<button ${extra.includes('type="submit"')?'':'type="button"'} class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${{settings:'<path d="m9 3-.7 2.2-2 .9-2.1-.5-1.5 2.6 1.5 1.7v2.2l-1.5 1.7 1.5 2.6 2.1-.5 2 .9L9 19h3l.7-2.2 2-.9 2.1.5 1.5-2.6-1.5-1.7V9.9l1.5-1.7-1.5-2.6-2.1.5-2-.9L12 3Z"/><circle cx="10.5" cy="11" r="3"/>',edit:'<path d="m15 5 4 4M4 20l5-1L20 8a2.8 2.8 0 0 0-4-4L5 15Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',media:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',home:'<path d="m3 11 9-8 9 8M5 10v11h14V10M9 21v-7h6v7"/>'}[name]||''}</svg>`;
let setupConfig=defaultSetup(),setupStage=0,setupSelected=0;
let stepFocus=null,stopPreviewTimer=()=>{};
let screen='home',hasDraft=false,mediaLoaded=false,opening=false;
let pack,media=new Map(),urls=new Map(),roundId,themeId,questionId,previewIndex=0,history=[],future=[],saveTimer,saveQueue=Promise.resolve(),saveRevision=0,savedRevision=0,storageOK=true,focused=false,uploadTarget;
const activeRound=()=>pack.rounds.find(r=>r.id===roundId)||pack.rounds[0];
const activeTheme=()=>activeRound()?.themes.find(t=>t.id===themeId)||activeRound()?.themes[0];
const activeQuestion=()=>activeTheme()?.questions.find(q=>q.id===questionId)||activeTheme()?.questions[0];
function select(r,t,q){roundId=r?.id;themeId=t?.id;questionId=q?.id;previewIndex=0;}
function snapshot(){history.push(structuredClone(pack));if(history.length>40)history.shift();future=[];}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function changed(redraw=true){persist();if(redraw)render();else{const undo=$('[data-action="undo"]'),redo=$('[data-action="redo"]');if(undo)undo.disabled=!history.length;if(redo)redo.disabled=!future.length;const status=$('.question-status');if(status){const bad=issues(pack,media).some(x=>x.question===activeQuestion()?.id);status.textContent=bad?'Черновик':'Готов к игре';status.classList.toggle('draft',bad);}}}
async function persist(){const data=structuredClone(pack),revision=++saveRevision;$('#save-status')?.replaceChildren(document.createTextNode('Сохраняем…'));saveQueue=saveQueue.catch(()=>{}).then(()=>storage.saveDraft(data));try{await saveQueue;savedRevision=revision;storageOK=true;hasDraft=true;if(revision===saveRevision)$('#save-status')?.replaceChildren(document.createTextNode('Сохранено на устройстве'));}catch{storageOK=false;$('#save-status')?.replaceChildren(document.createTextNode('Не сохранено'));toast('Не удалось сохранить. Скачайте .siq, чтобы не потерять изменения.');}}
const url=id=>{if(!media.has(id))return '';if(!urls.has(id))urls.set(id,URL.createObjectURL(media.get(id)));return urls.get(id);};

function board(){const r=activeRound(),q=activeQuestion(),bad=new Set(issues(pack,media).map(x=>x.question));return `<section class="studio-board-pane" aria-labelledby="board-title"><div class="studio-pane-heading"><div><h2 id="board-title">Игровое поле</h2><p>Выберите вопрос, чтобы собрать его сценарий.</p></div></div><div class="studio-board-scroll" data-round="${r?.id||''}"><div class="studio-board">${r?.themes.map(t=>`<div class="studio-board-row"><div class="studio-theme-name"><span title="${e(t.name)}">${e(t.name)}</span>${btn('theme-settings',icon('edit'),'studio-theme-edit',`data-id="${t.id}" aria-label="Настройки темы ${e(t.name)}"`)}</div><div class="studio-price-row">${t.questions.map(qq=>`<button type="button" class="studio-question-cell ${!bad.has(qq.id)?'complete':''}" data-action="board-question" data-theme="${t.id}" data-id="${qq.id}" ${qq.id===q?.id?'aria-current="true"':''} aria-label="${e(t.name)}, ${questionType(qq)==='stake'?'аукцион':'вопрос'} за ${qq.price}" title="${e(qq.steps.find(s=>s.type==='text')?.value||'Новый вопрос')}"><span>${r.type==='final'?'?':qq.price}</span><i aria-hidden="true"></i></button>`).join('')}${btn('board-add-question','+','studio-add-cell',`data-id="${t.id}" aria-label="Добавить вопрос в тему ${e(t.name)}"`)}</div></div>`).join('')||'<div class="studio-board-empty">Добавьте первую тему — здесь появятся ваши вопросы.</div>'}${btn('add-theme','+','studio-add-cell studio-add-theme','aria-label="Добавить тему" title="Добавить тему"')}</div></div><div class="studio-board-bottom"><div class="studio-board-legend"><span><i></i> В работе</span><span><i class="ready"></i> Готов</span></div></div></section>`;}
function editor(){const t=activeTheme(),q=activeQuestion();if(!q)return `<section class="studio-question-pane studio-empty"><span>✦</span><h2>С чего начнём?</h2><p>Добавьте тему или выберите вопрос на поле слева.</p>${btn(t?'add-question':activeRound()?'add-theme':'add-round','+ Добавить '+(t?'вопрос':activeRound()?'тему':'раунд'),'primary')}</section>`;const bad=issues(pack,media).some(x=>x.question===q.id);return `<section class="studio-question-pane" aria-labelledby="question-title"><div class="studio-question-heading"><div><p class="studio-question-theme">${e(t.name)}</p><h1 id="question-title">${activeRound()?.type==='final'?'Финальный вопрос':`Вопрос за ${q.price}`}<span class="question-status ${bad?'draft':''}">${bad?'В работе':'Готов к игре'}</span></h1></div><div class="studio-question-actions">${btn('preview','▷ Смотреть','secondary','title="Предпросмотр вопроса"')}${btn('question-settings',icon('edit'),'icon-button','aria-label="Изменить стоимость вопроса" title="Изменить стоимость"')}${btn('delete-question',icon('trash'),'icon-button studio-delete-question','aria-label="Удалить вопрос" title="Удалить вопрос"')}</div></div><div class="studio-question-content" data-question="${q.id}">${questionTypeHTML(q)}${scenarioHTML(q)}<section class="studio-answer"><div><h2>Правильный ответ</h2><span>До ответа видит только ведущий</span></div><label class="sr-only" for="correct-answer">Правильный ответ</label><input id="correct-answer" data-field="answer" value="${e(q.answer)}" placeholder="Что должны назвать игроки?"><details class="studio-extra"><summary>Варианты ответа и заметки</summary><label>Другие верные формулировки<textarea data-field="alternatives" placeholder="Каждый вариант с новой строки">${e(q.alternatives)}</textarea></label><label>Неверные ответы<textarea data-field="wrong" placeholder="Каждый вариант с новой строки">${e(q.wrong)}</textarea></label><label>Комментарий ведущему<textarea data-field="comment" placeholder="Уточнения и пояснения">${e(q.comment)}</textarea></label><label>Источник<input data-field="source" value="${e(q.source)}" placeholder="Ссылка или название источника"></label></details></section></div></section>`;}
function questionTypeHTML(q){const auction=questionType(q)==='stake';return `<section class="studio-question-type"><label for="question-type">Тип вопроса</label><select id="question-type" data-question-type aria-describedby="question-type-help">${Object.entries(questionTypes).map(([type,label])=>`<option value="${type}" ${questionType(q)===type?'selected':''}>${label}</option>`).join('')}</select><p id="question-type-help">${auction?`Перед показом вопроса SIGame проводит торги. Отвечает только победитель; он получает или теряет сумму своей ставки. Номинальная стоимость — ${q.price}.`:'Отвечает первый нажавший кнопку. После ошибки могут отвечать другие игроки.'}</p></section>`;}
function stepPalette(section,disabled=false){return `<div class="studio-step-palette"><div>${['text','image','audio','video'].map(type=>btn('add-step',`<span aria-hidden="true">${kinds[type][1]}</span> ${{text:'Текст',image:'Фото',audio:'Аудио',video:'Видео'}[type]}`,'studio-add-step',`data-type="${type}" data-section="${section}" ${disabled?'disabled':''}`)).join('')}</div></div>`;}
function scenarioHTML(q){
 const parts=scenarioParts(q.steps);
 const cards=steps=>steps.map(st=>stepCard(st,q.steps.indexOf(st),q)).join('');
 return `<div class="studio-steps"><section class="studio-scenario-section" data-section="before" aria-label="До ответа игроков"><div class="studio-section-divider"><h3>До ответа игроков</h3></div><div class="studio-section-steps">${cards(parts.before)}</div>${stepPalette('before')}</section><section class="studio-scenario-section studio-response-section" data-section="answer" aria-label="Ответ игроков"><div class="studio-section-steps">${parts.answer.length?cards(parts.answer):btn('add-step','+ Игроки отвечают','secondary','data-type="answer"')}</div></section><section class="studio-scenario-section" data-section="after" aria-label="После ответа игроков"><div class="studio-section-divider"><h3>${questionType(q)==='stake'?'После ответа или окончания времени':'После таймера или верного ответа'}</h3></div><div class="studio-section-steps">${cards(parts.after)}</div>${stepPalette('after',!parts.answer.length)}</section></div>`;
}
function durationControl(st,i){
 const custom=st.duration>0,label=st.type==='answer'?'Время на ответ':'Длительность шага';
 return `<div class="studio-duration"><label class="studio-check"><input type="checkbox" data-duration-toggle data-id="${st.id}" ${custom?'checked':''} aria-label="Своя длительность шага ${i+1}"> Своя длительность</label>${custom?`<div class="studio-duration-slider"><input type="range" min="1" max="60" step="1" data-step-field="duration" data-id="${st.id}" value="${Math.min(60,Math.max(1,st.duration))}" aria-label="${label}, шаг ${i+1}"><output class="studio-duration-value" data-id="${st.id}">${st.duration} сек</output></div><div class="studio-duration-scale"><span>1 сек</span><span>60 сек</span></div>${st.duration>60?`<p>В загруженном паке — ${st.duration} сек. Слайдер задаёт от 1 до 60 сек.</p>`:''}`:'<p>Время определит игра.</p>'}</div>`;
}
function stepCard(st,i,q){const [name,icon]=kinds[st.type];return `<details class="studio-step studio-type-${st.type} ${st.type==='answer'?'studio-answer-step':''}" data-step="${st.id}" ${stepFocus===st.id?'open':''}><summary><button type="button" class="studio-step-handle" draggable="true" aria-label="Перетащить шаг ${i+1}" title="Потяните, чтобы переместить шаг">⠿</button><span class="studio-step-number">${String(i+1).padStart(2,'0')}</span><span class="studio-step-symbol ${st.type}" aria-hidden="true">${icon}</span><span class="studio-step-label">${st.type==='answer'?answerLabel(q):name}${st.type==='answer'&&st.duration?` · ${st.duration} сек`: ''}</span><span class="studio-step-chevron" aria-hidden="true">⌄</span></summary><div class="studio-step-body">${st.type==='answer'?`${durationControl(st,i)}`:st.type==='text'?`<textarea class="studio-step-text" data-step-field="value" data-id="${st.id}" aria-label="Текст шага ${i+1}" placeholder="Напишите вопрос или часть истории…">${e(st.value)}</textarea>`:`<button type="button" class="studio-upload" data-action="upload" data-id="${st.id}">${st.mediaId&&st.type==='image'?`<img src="${url(st.mediaId)}" alt="${e(st.filename)}">`:`<span aria-hidden="true">${st.mediaId?'✓':'↥'}</span>`}<strong>${st.mediaId?e(st.filename):'Выбрать файл'}</strong><small>${st.mediaId?'Нажмите, чтобы заменить файл':st.type==='image'?'PNG, JPG, WebP или GIF':st.type==='audio'?'MP3, WAV или OGG':'MP4 или WebM'}</small></button>`}<div class="studio-step-bottom">${st.type!=='answer'?`<details class="studio-step-options"><summary>Параметры шага</summary>${durationControl(st,i)}<label class="studio-check"><input type="checkbox" data-step-field="wait" data-id="${st.id}" ${st.wait?'checked':''}> Пауза перед следующим шагом</label></details>`:'<span></span>'}<div class="studio-step-order">${btn('step-up','↑','icon-button',`data-id="${st.id}" aria-label="Переместить шаг выше" ${i===0?'disabled':''}`)}${btn('step-down','↓','icon-button',`data-id="${st.id}" aria-label="Переместить шаг ниже" ${i===q.steps.length-1?'disabled':''}`)}${btn('delete-step','×','icon-button',`data-id="${st.id}" aria-label="Удалить шаг"`)}</div></div></div></details>`;}
function mediaPage(){const used=new Map();for(const q of questions(pack))for(const s of q.steps)if(s.mediaId)used.set(s.mediaId,s);return `<div class="board-page"><div class="eyebrow">ВСЁ В ОДНОМ МЕСТЕ</div><h1>Медиатека</h1><p class="section-description">Файлы, которые используются в вашем паке. Добавляйте их в шагах вопросов.</p><div class="media-grid">${[...used.values()].map(s=>`<article class="media-card">${s.type==='image'?`<img src="${url(s.mediaId)}" alt="${e(s.filename)}">`:s.type==='audio'?`<audio controls src="${url(s.mediaId)}"></audio>`:`<video controls src="${url(s.mediaId)}"></video>`}<strong>${e(s.filename)}</strong><small>${kinds[s.type][0]} · ${((media.get(s.mediaId)?.size||0)/1024/1024).toFixed(1)} МБ</small></article>`).join('')||'<div class="empty media-empty"><span>▧</span><h2>Место для ваших находок</h2><p>Фото, музыка и видео появятся здесь,<br>когда вы добавите их в вопрос.</p></div>'}</div></div>`;}
function previewContent(q,index){if(!q)return '<p>Выберите вопрос</p>';const s=q.steps[index];if(!s)return '<p>Добавьте первый шаг</p>';if(s.type==='answer')return `<div class="answer-preview"><span>⌁</span><h3>${answerLabel(q)}</h3><p>Осталось <strong id="preview-countdown" role="timer">${s.duration||10}</strong> сек${s.duration?'':'<br>В предпросмотре — 10 сек; в игре — по её настройкам'}</p></div>`;if(s.type==='text')return `<p class="screen-text">${e(s.value)||'Текст вашего вопроса'}</p>`;if(!s.mediaId)return `<div class="screen-placeholder">${kinds[s.type][1]}<small>Загрузите ${s.type==='image'?'изображение':s.type==='audio'?'аудио':'видео'}</small></div>`;if(s.type==='image')return `<img src="${url(s.mediaId)}" alt="${e(s.filename)}">`;if(s.type==='audio')return `<div class="screen-audio"><span>♫</span><audio controls src="${url(s.mediaId)}"></audio></div>`;return `<video controls src="${url(s.mediaId)}"></video>`;}
function render(){document.body.classList.toggle('at-home',screen==='home');document.body.classList.toggle('at-setup',screen==='setup');document.body.classList.toggle('at-editor',screen==='editor');if(screen==='setup'){$('#app').innerHTML=setupHTML(setupConfig,setupStage,hasDraft,pack.name,setupSelected);return;}if(screen==='home'){$('#app').innerHTML=welcomeHTML(pack,hasDraft,storageOK);return;}const oldLogo=$('.studio-header .brand-logo'),oldBoard=$('.studio-board-scroll'),oldQuestion=$('.studio-question-content');const r=activeRound(),t=activeTheme(),q=activeQuestion();const boardScroll=oldBoard?.dataset.round===r?.id?{top:oldBoard.scrollTop,left:oldBoard.scrollLeft}:null,questionScroll=oldQuestion?.dataset.question===q?.id?oldQuestion.scrollTop:0;roundId=r?.id;themeId=t?.id;questionId=q?.id;if(!q?.steps.some(st=>st.id===stepFocus))stepFocus=q?.steps[0]?.id;$('#app').innerHTML=`<div class="studio-shell"><header class="studio-header"><a class="brand" href="./" data-action="home" aria-label="SIGameMaker — на главную"><img class="brand-logo" src="./assets/logo-horizontal.png" alt="SIGameMaker"></a><span class="studio-header-divider"></span><span class="studio-pack-name" title="${e(pack.name)}">${e(pack.name)}</span><span class="studio-save" id="save-status">${!storageOK?'Не сохранено':saveRevision>savedRevision?'Сохраняем…':'Сохранено на устройстве'}</span><div class="studio-history">${btn('undo','↶','icon-button','aria-label="Отменить" '+(!history.length?'disabled':''))}${btn('redo','↷','icon-button','aria-label="Повторить" '+(!future.length?'disabled':''))}</div><nav class="studio-header-actions" aria-label="Действия с паком">${btn('pack-settings',icon('settings')+'<span>Настройки</span>','studio-header-button','aria-label="Настройки пака"')}${btn('view-media',icon('media')+'<span>Медиатека</span>','studio-header-button')}${btn('home',icon('home')+'<span>В меню</span>','studio-header-button','aria-label="Вернуться в меню"')}</nav>${btn('export','↓ Экспорт .siq','primary')}</header><div class="studio-round-bar"><nav class="studio-round-tabs" aria-label="Раунды пака">${pack.rounds.map((rr,i)=>`<div class="studio-round-item" ${rr.id===r?.id?'data-current="true"':''}>${btn('select-round',`<span>${rr.type==='final'?'⚑':String(i+1).padStart(2,'0')}</span><span class="studio-round-name">${e(rr.name)}</span>`,'studio-round-tab',`data-id="${rr.id}" ${rr.id===r?.id?'aria-current="true"':''}`)}${btn('round-settings',icon('settings'),'studio-round-settings',`data-id="${rr.id}" aria-label="Настройки раунда ${e(rr.name)}" title="Настройки раунда ${e(rr.name)}"`)}</div>`).join('')}${btn('add-round','+','studio-add-round','aria-label="Добавить раунд" title="Добавить раунд"')}</nav></div><main class="studio-workspace">${board()}${editor()}</main></div>`;if(oldLogo)$('.studio-header .brand-logo')?.replaceWith(oldLogo);if(boardScroll)$('.studio-board-scroll').scrollTo(boardScroll.left,boardScroll.top);const content=$('.studio-question-content');if(content)content.scrollTop=questionScroll;}
function dialog(title,body,foot=''){stopPreviewTimer();const d=$('#dialog');d.className='';d.innerHTML=`<div class="dialog-heading"><h2>${title}</h2>${btn('close-dialog','×','icon-button','aria-label="Закрыть"')}</div>${body}${foot?`<div class="dialog-footer">${foot}</div>`:''}`;if(!d.open)d.showModal();}
function settings(type,id){const r=type==='round'&&id?pack.rounds.find(r=>r.id===id):activeRound(),t=id?r?.themes.find(t=>t.id===id):activeTheme(),q=activeQuestion();let target=type==='pack'?pack:type==='round'?r:type==='theme'?t:q;if(!target)return;if(type==='theme')themeId=target.id;const title={pack:'Настройки пака',round:'Настройки раунда',theme:'Настройки темы',question:'Стоимость вопроса'}[type];const input=(label,field,value,attrs='')=>`<label>${label}<input name="${field}" value="${e(value)}" ${attrs}></label>`;dialog(title,`<form id="settings-form" data-type="${type}" data-id="${target.id}" class="settings-form">${type==='question'?input('Стоимость','price',q.price,'type="number" min="0" max="1000000" step="1" required'):input('Название','name',target.name,'required maxlength="150"')}${type==='pack'?`${input('Автор','author',pack.author)}<label>Описание<textarea name="description">${e(pack.description)}</textarea></label><div class="form-row"><label>Сложность<select name="difficulty">${Array.from({length:10},(_,i)=>`<option ${pack.difficulty===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label><label>Язык<select name="language"><option value="ru-RU" ${pack.language==='ru-RU'?'selected':''}>Русский</option><option value="en-US" ${pack.language==='en-US'?'selected':''}>English</option></select></label></div>`:''}${type==='round'?`<label>Тип раунда<select name="type"><option value="standard" ${r.type==='standard'?'selected':''}>Обычный раунд</option><option value="final" ${r.type==='final'?'selected':''}>Финал</option></select></label>`:''}<div class="dialog-footer">${['round','theme'].includes(type)?btn('delete-'+type,'Удалить '+({round:'раунд',theme:'тему'}[type]),'danger',`data-id="${target.id}"`):''}${btn('save-settings','Сохранить','primary','type="submit"')}</div></form>`);}
function showValidation(forExport=false){const list=issues(pack,media);if(!list.length){if(forExport)return download();toast('Пак готов к игре!');return;}dialog('Немного доработаем пак',`<p class="dialog-description">Перед экспортом исправьте ${list.length} замечаний.</p><div class="issues-list">${list.map(x=>`<button data-action="go-issue" data-round="${x.round||''}" data-theme="${x.theme||''}" data-id="${x.question||''}"><span>!</span>${e(x.message)} <b>›</b></button>`).join('')}</div>`);}
async function download(){const b=$('[data-action="export"]');if(b)b.disabled=true;try{const bytes=await exportSIQ(pack,media),link=document.createElement('a'),href=URL.createObjectURL(new Blob([bytes],{type:'application/zip'}));link.href=href;link.download=`${pack.name.replace(/[\\/:*?"<>|]/g,'_')||'pack'}.siq`;link.click();setTimeout(()=>URL.revokeObjectURL(href),10000);toast('Пак .siq готов. Загрузите его в SIGame.');}catch(err){toast(err.message);}finally{if(b)b.disabled=false;}}
function showPreview(){if(!activeQuestion()?.steps.length)return toast('Сначала добавьте шаг в сценарий.');previewIndex=0;paintPreviewDialog();}
function paintPreviewDialog(){
 const q=activeQuestion();if(!q)return;
 const st=q.steps[previewIndex],marker=q.steps.findIndex(s=>s.type==='answer'),revealing=!st||marker>=0&&previewIndex>marker;
 const content=st?previewContent(q,previewIndex):`<div class="screen-text">${e(q.answer)||'Ответ ещё не указан'}</div>`;
 dialog('Предпросмотр вопроса',`<div class="full-preview"><div class="game-screen"><div class="screen-header"><span>${e(activeTheme()?.name)}</span><b>${questionType(q)==='stake'?'Аукцион':q.price}</b></div><div class="screen-content">${content}</div><div class="screen-brand">${revealing?'ПРАВИЛЬНЫЙ ОТВЕТ':'СВОЯ ИГРА ✦'}</div></div><div class="preview-control"><span>${st?`Шаг ${previewIndex+1} из ${q.steps.length}`:'Правильный ответ'}</span><div>${btn('play-prev','←','secondary',previewIndex===0?'disabled aria-label="Предыдущий шаг"':'aria-label="Предыдущий шаг"')}${st?.type==='answer'?btn('play-correct','Ответили верно','primary'):btn(revealing&&previewIndex>=q.steps.length-1?'close-dialog':'play-next',revealing&&previewIndex>=q.steps.length-1?'Завершить просмотр':previewIndex===q.steps.length-1?'Правильный ответ':'Следующий шаг →','primary')}</div></div><div class="preview-restart">${btn('preview','↻ Начать заново','secondary')}<p>${questionType(q)==='stake'?'Торги проходят в SIGame перед показом вопроса; здесь показан сценарий для победителя. ':''}Шаги переключаются вручную. Таймер ответа отсчитывается автоматически.</p></div></div>`);
 $('#dialog').classList.add('studio-preview-dialog');
 if(st?.type==='answer')stopPreviewTimer=countdown(st.duration||10,left=>{const label=$('#preview-countdown');if(label)label.textContent=left;},()=>{if($('#dialog').open)actions['play-next']();});
 const player=$('#dialog audio, #dialog video');if(player)player.play().catch(()=>{});
}

function remove(type,id){if(!confirm(`Удалить ${ {round:'раунд со всеми темами',theme:'тему со всеми вопросами',question:'этот вопрос'}[type]}? Действие можно отменить.`))return;snapshot();if(type==='round')pack.rounds=pack.rounds.filter(r=>r.id!==(id||activeRound().id));if(type==='theme')activeRound().themes=activeRound().themes.filter(t=>t.id!==activeTheme().id);if(type==='question')activeTheme().questions=activeTheme().questions.filter(q=>q.id!==activeQuestion().id);$('#dialog').close();changed();}
const actions={
 'close-dialog':()=>$('#dialog').close(),
'view-media':()=>{dialog('Медиатека',mediaPage());$('#dialog').classList.add('studio-wide-dialog');},
 'select-round':b=>{const r=pack.rounds.find(r=>r.id===b.dataset.id);select(r,r.themes[0],r.themes[0]?.questions[0]);render();},
 'select-theme':b=>{const t=activeRound().themes.find(t=>t.id===b.dataset.id);select(activeRound(),t,t.questions[0]);render();},
 'select-question':b=>{questionId=b.dataset.id;previewIndex=0;render();},
 'board-question':b=>{themeId=b.dataset.theme;questionId=b.dataset.id;previewIndex=0;render();},
 'add-round':()=>{snapshot();const r={id:uid(),name:`Раунд ${pack.rounds.length+1}`,type:'standard',themes:[theme()]};pack.rounds.push(r);select(r,r.themes[0],r.themes[0].questions[0]);changed();settings('round');},
 'add-theme':()=>{if(!activeRound())return actions['add-round']();snapshot();const t=theme('Новая тема',activeRound().type==='final'?0:100*(pack.rounds.indexOf(activeRound())+1));if(activeRound().type==='final')t.questions=[question(0)];activeRound().themes.push(t);select(activeRound(),t,t.questions[0]);changed();settings('theme');},
 'add-question':()=>{if(!activeTheme())return actions['add-theme']();snapshot();const qs=activeTheme().questions,q=question((qs.length?Math.max(...qs.map(q=>q.price)):0)+100);qs.push(q);questionId=q.id;changed();},
 'board-add-question':b=>{themeId=b.dataset.id;actions['add-question']();},
 'add-step':b=>{const q=activeQuestion();if(!q)return;const st=step(b.dataset.type),next=insertScenarioStep(q.steps,st,b.dataset.section);if(next===q.steps)return;snapshot();q.steps=next;previewIndex=q.steps.indexOf(st);stepFocus=st.id;changed();const detail=$(`.studio-step[data-step="${st.id}"]`);detail?.scrollIntoView({block:'nearest'});detail?.querySelector('textarea')?.focus({preventScroll:true});},
 'delete-step':b=>{snapshot();activeQuestion().steps=activeQuestion().steps.filter(s=>s.id!==b.dataset.id);changed();},
 'step-up':b=>moveStep(b,-1),'step-down':b=>moveStep(b,1),
 'upload':b=>{uploadTarget={q:activeQuestion(),id:b.dataset.id};const s=uploadTarget.q.steps.find(s=>s.id===uploadTarget.id);$('#media-file').accept=({image:'.png,.jpg,.jpeg,.webp,.gif',audio:'.mp3,.wav,.ogg',video:'.mp4,.webm'})[s.type];$('#media-file').click();},
 'pack-settings':()=>settings('pack'),'round-settings':b=>settings('round',b?.dataset.id),'theme-settings':b=>settings('theme',b?.dataset.id),'question-settings':()=>settings('question'),
 'delete-round':b=>remove('round',b?.dataset.id),'delete-theme':()=>remove('theme'),'delete-question':()=>remove('question'),
 'new-pack':()=>createPackForm(),
 'create-pack':()=>createPackForm(),
 'setup-cancel':()=>{screen='home';render();window.scrollTo(0,0);},
 'setup-select-round':b=>{const current=$('#setup-form input[name^="roundName"]');if(current&&!current.reportValidity())return;captureSetup();setupSelected=Number(b.dataset.index);render();const tab=$('.structure-filmstrip button[aria-current]');tab?.focus({preventScroll:true});tab?.scrollIntoView({block:'nearest',inline:'nearest'});},
 'setup-back':()=>{captureSetup();setupStage=Math.max(0,setupStage-1);render();window.scrollTo(0,0);},
 'setup-edit':b=>{setupStage=Number(b.dataset.stage);render();window.scrollTo(0,0);},
 'home':async()=>{await saveQueue.catch(()=>{});screen='home';render();},
 'resume-pack':()=>enterEditor(),
 'open-demo':()=>openDemo(),
 'export':()=>showValidation(true),'import':()=>$('#import-file').click(),
 'undo':()=>{if(!history.length)return;future.push(structuredClone(pack));pack=history.pop();changed();},'redo':()=>{if(!future.length)return;history.push(structuredClone(pack));pack=future.pop();changed();},
 'preview':()=>showPreview(),
 'play-correct':()=>{const q=activeQuestion();previewIndex=q.steps.findLastIndex(s=>s.type==='answer');actions['play-next']();},
 'play-prev':()=>{previewIndex=Math.max(0,previewIndex-1);paintPreviewDialog();},'play-next':()=>{const q=activeQuestion();previewIndex=Math.min(q.steps.length,previewIndex+1);paintPreviewDialog();},
 'go-issue':b=>{$('#dialog').close();if(!b.dataset.id)return settings('pack');roundId=b.dataset.round;themeId=b.dataset.theme;questionId=b.dataset.id;render();},
 'help':()=>dialog('Соберите свой хороший вечер',`<div class="help-content"><p><b>1. Постройте игровое поле</b><br>Создайте раунды и темы. В каждой теме уже есть пять слотов для вопросов.</p><p><b>2. Расскажите вопрос по шагам</b><br>Выберите обычный вопрос или аукцион. В аукционе SIGame проводит торги до показа вопроса. Добавьте текст, картинку, аудио или видео. Перетаскивайте шаги за ручку ⠿ или используйте стрелки. Шаг «Игроки отвечают» отделяет вопрос от раскрытия ответа.</p><p><b>3. Укажите правильный ответ</b><br>Добавьте допустимые формулировки и заметки ведущему.</p><p><b>4. Проверьте и скачайте .siq</b><br>Экспорт включает все медиафайлы. Откройте SIGame Online и выберите скачанный пак при создании игры.</p><p class="muted">Черновик хранится в этом браузере. Для резервной копии скачайте .siq. Импортируются обычные вопросы и аукционы SIQ 4 и 5; остальные специальные типы и скрипты пока не поддерживаются.</p><p><a href="https://github.com/VladimirKhil/SI/wiki/SIQ-file-format-version-5" target="_blank" rel="noreferrer">О формате SIQ ↗</a></p></div>`,btn('close-dialog','Всё понятно','primary'))
};
installStepDrag({getQuestion:()=>screen==='editor'?activeQuestion():null,onMove:({id,beforeId,questionId})=>{const q=activeQuestion();if(q?.id!==questionId)return;const next=reorderSteps(q.steps,id,beforeId);if(next===q.steps)return;snapshot();q.steps=next;stepFocus=id;changed();toast('Порядок шагов изменён');}});
function moveStep(b,delta){const a=activeQuestion().steps,i=a.findIndex(s=>s.id===b.dataset.id);if(i+delta<0||i+delta>=a.length)return;snapshot();[a[i],a[i+delta]]=[a[i+delta],a[i]];changed();}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled||b.type==='submit'&&b.closest('form'))return;if(b.tagName==='A')ev.preventDefault();actions[b.dataset.action]?.(b);});
document.addEventListener('submit',ev=>{if(ev.target.id==='setup-form'){ev.preventDefault();captureSetup();if(setupStage===0&&!setupConfig.name.trim()){const input=$('#setup-form input[name="name"]');input.setCustomValidity('Введите название пака.');input.reportValidity();input.addEventListener('input',()=>input.setCustomValidity(''),{once:true});return;}if(setupStage<2){setupStage++;render();window.scrollTo(0,0);}else{try{const next=buildPack(setupConfig);startPack(next,next.name);}catch(err){toast(err.message);}}return;}if(ev.target.id!=='settings-form')return;ev.preventDefault();const form=ev.target,type=form.dataset.type,target=type==='pack'?pack:type==='round'?pack.rounds.find(r=>r.id===form.dataset.id):type==='theme'?activeTheme():activeQuestion();snapshot();for(const [key,value]of new FormData(form))target[key]=['price','difficulty'].includes(key)?Number(value):value.trim();$('#dialog').close();changed();});
function syncQuestionState(){const q=activeQuestion();if(!q)return;for(const st of q.steps){if(st.type!=='answer')continue;const label=$(`.studio-step[data-step="${st.id}"] .studio-step-label`);if(label)label.textContent=answerLabel(q)+(st.duration?` · ${st.duration} сек`:'');}const bad=issues(pack,media).some(x=>x.question===q.id);const cell=$(`.studio-question-cell[data-id="${q.id}"]`);if(cell){cell.classList.toggle('complete',!bad);cell.title=q.steps.find(st=>st.type==='text')?.value||'Новый вопрос';}}

document.addEventListener('toggle',ev=>{const detail=ev.target;if(!detail.matches?.('.studio-step')||!detail.open||!detail.isConnected)return;stepFocus=detail.dataset.step;document.querySelectorAll('.studio-step[open]').forEach(other=>{if(other!==detail)other.open=false;});},true);
document.addEventListener('focusin',ev=>{if(ev.target.matches('[data-field],[data-step-field]'))focused=false;});
document.addEventListener('input',ev=>{const el=ev.target,q=activeQuestion();if(!q||!el.matches('[data-field],[data-step-field]'))return;if(!focused){snapshot();focused=true;}if(el.dataset.field)q[el.dataset.field]=el.value;else{const s=q.steps.find(s=>s.id===el.dataset.id);s[el.dataset.stepField]=el.type==='checkbox'?el.checked:el.type==='range'?Math.max(1,Math.min(60,Math.round(Number(el.value)||1))):el.value;}if(el.dataset.stepField==='duration'){const out=$(`.studio-duration-value[data-id="${el.dataset.id}"]`);if(out)out.textContent=`${q.steps.find(st=>st.id===el.dataset.id).duration} сек`;}changed(false);syncQuestionState();});
document.addEventListener('change',ev=>{const el=ev.target;if(!el.matches('[data-question-type]'))return;const q=activeQuestion();if(!q||!Object.hasOwn(questionTypes,el.value)||questionType(q)===el.value)return;snapshot();q.type=el.value;focused=false;changed();$('#question-type')?.focus({preventScroll:true});});
document.addEventListener('change',ev=>{const el=ev.target;if(!el.matches('[data-duration-toggle]'))return;const q=activeQuestion(),st=q?.steps.find(st=>st.id===el.dataset.id);if(!st)return;snapshot();if(el.checked)st.duration=st.customDuration||10;else{st.customDuration=st.duration;st.duration=0;}focused=false;el.closest('.studio-duration').outerHTML=durationControl(st,q.steps.indexOf(st));changed(false);syncQuestionState();});
document.addEventListener('change',ev=>{if(ev.target.matches('[data-field],[data-step-field]')){focused=false;}});
document.addEventListener('keydown',ev=>{if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='z'&&!ev.target.matches('input,textarea')&&!$('#dialog').open&&screen==='editor'){ev.preventDefault();actions[ev.shiftKey?'redo':'undo']();}});
$('#dialog').addEventListener('close',()=>{stopPreviewTimer();$('#dialog').querySelectorAll('audio,video').forEach(player=>player.pause());});
$('#dialog').addEventListener('cancel',()=>stopPreviewTimer());
// Dialog padding and the backdrop never dismiss a form. Close explicitly or press Escape.
$('#media-file').addEventListener('change',async ev=>{const file=ev.target.files[0];ev.target.value='';if(!file||!uploadTarget)return;if(file.size>100*1024*1024)return toast('Выберите файл до 100 МБ');const {q,id}=uploadTarget,s=q.steps.find(s=>s.id===id);if(!s)return;const allowed={image:['png','jpg','jpeg','webp','gif'],audio:['mp3','wav','ogg'],video:['mp4','webm']};if(!allowed[s.type].includes(file.name.split('.').pop().toLowerCase()))return toast('Формат файла не подходит для этого шага');try{const mediaId=uid();await storage.putMedia(mediaId,file);snapshot();media.set(mediaId,file);s.mediaId=mediaId;s.filename=file.name;s.value='';changed();toast('Файл добавлен и сохранён на устройстве');}catch{toast('Не удалось сохранить файл. Возможно, закончилось место в браузере.');}});
$('#import-file').addEventListener('change',async ev=>{const file=ev.target.files[0];ev.target.value='';if(!file)return;if(file.size>250*1024*1024)return toast('Пак должен быть меньше 250 МБ');try{const result=importSIQ(new Uint8Array(await file.arrayBuffer()));if(hasDraft&&!confirm(`Открыть «${result.pack.name}» вместо черновика «${pack.name}»? Для отдельной копии сначала скачайте текущий пак. Замену можно отменить в редакторе.`))return;for(const [id,blob]of result.media)await storage.putMedia(id,blob);await loadMedia();snapshot();pack=result.pack;for(const [id,blob]of result.media)media.set(id,blob);select(pack.rounds[0],pack.rounds[0]?.themes[0],pack.rounds[0]?.themes[0]?.questions[0]);screen='editor';$('#dialog').close();changed();toast('Пак открыт');}catch(err){dialog('Не удалось открыть пак',`<p class="dialog-description">${e(err.message)}</p>`,btn('close-dialog','Понятно','primary'));}});
window.addEventListener('beforeunload',ev=>{if(!storageOK||saveRevision>savedRevision){ev.preventDefault();ev.returnValue='';}});
async function loadMedia(){if(mediaLoaded)return;if(!storageOK&&!hasDraft){mediaLoaded=true;return;}try{media=await storage.getMedia();mediaLoaded=true;}catch{storageOK=false;toast('Не удалось загрузить медиа из браузера.');throw Error('Не удалось восстановить медиафайлы черновика.');}}
async function enterEditor(){if(opening)return;opening=true;try{await loadMedia();screen='editor';render();}catch(err){toast(err.message);}finally{opening=false;}}
function captureSetup(){const form=$('#setup-form');if(!form)return;const data=new FormData(form);if(setupStage===0){setupConfig.name=String(data.get('name')||'');setupConfig.author=String(data.get('author')||'');setupConfig.language=String(data.get('language')||'ru-RU');}if(setupStage===1){for(let i=0;i<setupConfig.rounds.length;i++){if(data.has(`roundName${i}`))setupConfig.rounds[i].name=String(data.get(`roundName${i}`));if(data.has(`roundThemes${i}`))setupConfig.rounds[i].themes=Number(data.get(`roundThemes${i}`));}for(const k of ['questions','basePrice','priceStep'])setupConfig[k]=Number(data.get(k));if(data.has('finalThemes'))setupConfig.finalThemes=Number(data.get('finalThemes'));setupConfig.hasFinal=data.has('hasFinal');setupConfig.multiplyPrices=data.has('multiplyPrices');}}
function createPackForm(){if($('#dialog').open)$('#dialog').close();setupConfig=defaultSetup();setupStage=0;setupSelected=0;screen='setup';render();window.scrollTo(0,0);}
function updateSetupPreview(){const preview=$('#setup-structure-preview');if(!preview)return;const stripScroll=preview.querySelector('.structure-filmstrip')?.scrollLeft||0,board=preview.querySelector('.structure-screen-scroll'),top=board?.scrollTop||0,left=board?.scrollLeft||0;preview.innerHTML=setupPreviewHTML(setupConfig,setupSelected);preview.querySelector('.structure-filmstrip').scrollLeft=stripScroll;preview.querySelector('.structure-screen-scroll').scrollTo(left,top);}
document.addEventListener('input',ev=>{if(screen!=='setup'||setupStage!==1||!ev.target.closest('#setup-form'))return;captureSetup();if(ev.target.name==='roundCount'){const n=Number(ev.target.value);if(!Number.isInteger(n)||n<1||n>10)return;while(setupConfig.rounds.length<n)setupConfig.rounds.push({name:`Раунд ${setupConfig.rounds.length+1}`,themes:6});setupConfig.rounds.length=n;setupSelected=Math.min(setupSelected,n-1);$('.setup-rounds').innerHTML=setupRoundsHTML(setupConfig,setupSelected);}if(ev.target.name!=='hasFinal')updateSetupPreview();});
document.addEventListener('change',ev=>{if(screen!=='setup'||setupStage!==1)return;if(ev.target.name==='hasFinal'){captureSetup();if(!setupConfig.hasFinal)setupSelected=Math.min(setupSelected,setupConfig.rounds.length-1);render();}else if(ev.target.name==='multiplyPrices'){captureSetup();updateSetupPreview();}});

async function startPack(next,name){if(opening)return;opening=true;try{await loadMedia();if(hasDraft)snapshot();next.name=name;pack=next;select(pack.rounds[0],pack.rounds[0]?.themes[0],pack.rounds[0]?.themes[0]?.questions[0]);$('#dialog').close();screen='editor';changed();}catch(err){toast(err.message);}finally{opening=false;}}
async function openDemo(){if(hasDraft&&!confirm(`Открыть пример вместо черновика «${pack.name}»? Для отдельной копии сначала скачайте текущий пак. Замену можно отменить в редакторе.`))return;await startPack(initial(true),'Хороший вечер');}
try{await storage.openDB();const draft=await storage.getDraft();hasDraft=!!draft;pack=draft||initial(false);}catch{pack=initial(false);storageOK=false;toast('Браузер не разрешил автосохранение. Скачивайте .siq для сохранения работы.');}select(pack.rounds[0],pack.rounds[0]?.themes[0],pack.rounds[0]?.themes[0]?.questions[0]);render();
